 let page=options.initialPage??'loadout',stack:ViewState[]=[],visible=false,disposed=false,executing=false,release:(()=>void)|undefined,opener:HTMLElement|null=null;
 let request=0,lastSignature='',lastPhase=host.phase(),cleanupFx=()=>{},cleanupSlots=()=>{},message='',isError=false,feedbackTimer=0,operationTimer=0,operation:Operation|undefined;
 let selected=new Set<string>(),query='',filters=newFilters(),sort='quality',direction=-1,pageNumber=1,filtersVisible=false,selectedSlot='',detailId='',detailAtlas=false,currentList:EquipmentItem[]=[];
 let heroMode=false,heroId:HeroId='raynor',heroState:EquipmentItem['pollution']='none',craftQuality:Quality=3,craftTemplate='',craftSlot:EquipmentSlot|''='',pending:CommandEnvelope|undefined;
 let dialogReturn:{act?:string;id?:string;index?:string}|undefined,lastItemClick:{id:string;page:StarshipPage;time:number}|undefined;
 let renameIndex:number|undefined,renameValue='',renameError='';
