 const account=()=>host.account(),outside=()=>['outside','settled'].includes(host.phase()),pageSize=()=>page==='loadout'?16:page==='warehouse'?30:24;
 root.classList.add('starship-ui');root.hidden=true;root.dataset.capturesBattleInput='true';
 let summaryAnchor:HTMLElement|undefined,summaryTip:HTMLElement|undefined;
 function hideSummary(){summaryAnchor?.removeAttribute('aria-describedby');summaryTip?.remove();summaryTip=undefined;summaryAnchor=undefined;}
 function showSummary(target:HTMLElement){
  const anchor=target.closest<HTMLElement>('[data-act="detail"],[data-act="catalog-detail"],[data-act="slot"]');if(!anchor||anchor===summaryAnchor)return;
  hideSummary();const id=anchor.dataset.act==='slot'?account().equipped[host.race()][anchor.dataset.id as EquipmentSlot]:anchor.dataset.id;
  if(id===detailId)return;
  const item=anchor.dataset.act==='catalog-detail'?catalogRows.find(r=>r.id===id):undefined;
  const gear=item?catalogItem(item):id?account().items[id]:undefined;if(!gear)return;
  const description=equipmentDescription(gear,equippedItems(account(),host.race())),tip=document.createElement('div');
  tip.id=root.id+'-summary';tip.className='equipment-tooltip rarity-'+gear.quality;tip.setAttribute('role','tooltip');
  tip.innerHTML=`<strong>${esc(presentation(gear).name)} <small>${qualityNames[gear.quality]}</small></strong><p>${esc(description.brief)}</p>`;
  document.body.append(tip);summaryAnchor=anchor;summaryTip=tip;anchor.setAttribute('aria-describedby',tip.id);
  const box=anchor.getBoundingClientRect(),size=tip.getBoundingClientRect(),left=Math.max(8,Math.min(window.innerWidth-size.width-8,box.left)),below=box.bottom+8;
  tip.style.left=left+'px';tip.style.top=Math.max(8,Math.min(window.innerHeight-size.height-8,below+size.height<=window.innerHeight?below:box.top-size.height-8))+'px';
 }
 root.addEventListener('pointerover',event=>{if(event.pointerType!=='touch'&&matchMedia('(hover:hover)').matches)showSummary(event.target as HTMLElement);},{signal:abort.signal});
 root.addEventListener('pointerout',event=>{if(summaryAnchor&&!summaryAnchor.contains(event.relatedTarget as Node|null))hideSummary();},{signal:abort.signal});
